def sembrar_y_pasar_delegaciones(apps, schema_editor):
    """Siembra los roles de proyecto y pasa cada delegación a un miembro: con edición, Supervisor; sin, Observador."""
    from Projects.catalogo_permisos import ROLES_DE_PROYECTO, SUPERVISOR, OBSERVADOR
    RolProyecto = apps.get_model('Projects', 'RolProyecto')
    MiembroProyecto = apps.get_model('Projects', 'MiembroProyecto')
    Delegacion = apps.get_model('Projects', 'DelegacionSupervision')
    roles = {}
    for r in ROLES_DE_PROYECTO:
        roles[r['nombre']], _ = RolProyecto.objects.update_or_create(
            nombre=r['nombre'],
            defaults={'descripcion': r['descripcion'], 'permisos': r['permisos'], 'orden': r['orden'], 'is_system': True},
        )
    for d in Delegacion.objects.all():
        MiembroProyecto.objects.create(
            proyecto_id=d.proyecto_id, usuario_id=d.supervisor_id, rol=roles[SUPERVISOR if d.puede_editar else OBSERVADOR],
            desde=d.creada_en.date(), hasta=d.expira_en, activo=d.activa, otorgado_por_id=d.otorgado_por_id,
            motivo='Delegación de supervisión',
        )


